47	namespace xls::dslx {
48	
49	using ModuleMember =
50	    std::variant<Function*, Proc*, TestFunction*, TestProc*, QuickCheck*,
51	                 TypeAlias*, StructDef*, ProcAlias*, ProcDef*, ConstantDef*,
52	                 EnumDef*, Import*, Use*, ConstAssert*, Impl*, Trait*,
53	                 VerbatimNode*, FuzzTestFunction*>;
54	
55	// Returns all the NameDefs defined by the given module member.
56	//
57	// Note that generally there is either zero or one, but for `Use` in particular
58	// there may be many.
59	//
60	// Note: this returns nullptr for constructs that do not define a name, e.g.
61	// `ConstAssert`.
62	std::vector<NameDef*> ModuleMemberGetNameDefs(const ModuleMember& mm);
63	
64	// Returns the starting position of the given module member.
65	//
66	// This is sometimes used in reporting; e.g. for test metadata, instead of a
67	// full span.
68	Pos GetPos(const ModuleMember& module_member);
69	
70	std::string_view GetModuleMemberTypeName(const ModuleMember& module_member);
71	
72	enum class ModuleAttribute : uint8_t {
73	  // Suppresses the "constant naming" warning.
74	  kAllowNonstandardConstantNaming,
75	
76	  kAllowNonstandardMemberNaming,
77	
78	  kTypeInferenceVersion1,
79	
80	  kTypeInferenceVersion2,
81	
82	  // Enable "use" syntax instead of "import" for this module.
83	  kAllowUseSyntax,
84	
85	  // Enable #channel() attributes for this module.
86	  kChannelAttributes,
87	
88	  // Enable read and write with optional labels for state access for this
89	  // module.
90	  kExplicitStateAccess,
91	
92	  kGenerics,
93	
94	  // Enable `trait` declarations.
95	  kTraits,
96	};
97	
98	// Represents a syntactic module in the AST.
99	//
100	// Modules contain top-level definitions such as functions and tests.
101	//
102	// Attributes:
103	//   name: Name of this module.
104	//   top: Top-level module constructs; e.g. functions, tests. Given as a
105	//    sequence instead of a mapping in case there are unnamed constructs at the
106	//    module level (e.g. metadata, docstrings).
107	//   fs_path: Name of the filesystem path that led to this module's AST -- if
108	//    the AST was constructed in-memory this value will be nullopt. Generally
109	//    this was relative to the main binary's $CWD (which is often a place like
110	//    Bazel's execution root) -- this helps output be deterministic even when
111	//    running distributed compilation.
112	class Module : public AstNode {
113	 public:
114	  Module(std::string name, std::optional<std::filesystem::path> fs_path,
115	         FileTable& file_table);
116	
117	  ~Module() override;
118	
119	  Module(Module&& other) = default;
120	  Module& operator=(Module&& other) = default;
121	
122	  AstNodeKind kind() const override { return AstNodeKind::kModule; }
123	
124	  FileTable& file_name() const {
125	    CHECK(file_table_ != nullptr);
126	    return *file_table_;
127	  }
128	
129	  absl::Status Accept(AstNodeVisitor* v) const override {
130	    return v->HandleModule(this);
131	  }
132	  std::optional<Span> GetSpan() const override { return span_; }
133	
134	  // Note: should generally only be called by the parser once the entire module
135	  // has been parsed, at which point the extent (limit position) is known.
136	  //
137	  // Note: After module parsing, span() is safe to call as an accessor instead
138	  // of GetSpan().
139	  void set_span(Span span) { span_ = span; }
140	
141	  const Span& span() const { return span_.value(); }
142	
143	  std::string_view GetNodeTypeName() const override { return "Module"; }
144	  std::vector<AstNode*> GetChildren(bool want_types) const override;
145	
146	  std::string ToString() const override;
147	
148	  template <typename T, typename... Args>
149	  T* Make(Args&&... args) {
150	    static_assert(!std::is_same<T, BuiltinNameDef>::value,
151	                  "Use Module::GetOrCreateBuiltinNameDef()");
152	    return MakeInternal<T, Args...>(std::forward<Args>(args)...);
153	  }
154	
155	  BuiltinNameDef* GetOrCreateBuiltinNameDef(std::string_view name) {
156	    auto it = builtin_name_defs_.find(name);
157	    if (it == builtin_name_defs_.end()) {
158	      BuiltinNameDef* bnd = MakeInternal<BuiltinNameDef>(std::string(name));
159	      builtin_name_defs_.emplace_hint(it, std::string(name), bnd);
160	      return bnd;
161	    }
162	    return it->second;
163	  }
164	
165	  BuiltinNameDef* GetOrCreateBuiltinNameDef(BuiltinType builtin_type) {
166	    return GetOrCreateBuiltinNameDef(BuiltinTypeToString(builtin_type));
167	  }
168	
169	  using MakeCollisionError = std::function<absl::Status(
170	      std::string_view module_name, std::string_view member_name,
171	      const Span& existing_span, const AstNode* existing_node,
172	      const Span& new_span, const AstNode* new_node)>;
173	
174	  // Adds a top level "member" to the module. Invokes make_collision_error if
175	  // there is a naming collision at module scope -- this is done so that errors
176	  // can be layered appropriately and injected in from outside code (e.g. the
177	  // parser). If nullptr is given, then a non-positional InvalidArgumentError is
178	  // raised.
179	  absl::Status AddTop(ModuleMember member,
180	                      const MakeCollisionError& make_collision_error);
181	
182	  // Gets the element in this module with the given target_name, or returns
183	  // `nullopt`.
184	  template <typename T>
185	  std::optional<T*> GetMember(std::string_view target_name) const {
186	    const auto it = top_by_name_.find(target_name);
187	    return it == top_by_name_.end() || !std::holds_alternative<T*>(it->second)
188	               ? std::nullopt
189	               : std::make_optional(std::get<T*>(it->second));
190	  }
191	
192	  // Inserts a top-level member immediately after `target_member`. Behaves like
193	  // `AddTop` with respect to collision checks.
194	  absl::Status InsertTopAfter(
195	      const AstNode* target_member, ModuleMember member,
196	      const MakeCollisionError& make_collision_error = nullptr);
197	
198	  // Inserts a top-level member immediately before `target_member`. Behaves like
199	  // `AddTop` with respect to collision checks.
200	  absl::Status InsertTopBefore(
201	      const AstNode* target_member, ModuleMember member,
202	      const MakeCollisionError& make_collision_error = nullptr);
203	
204	  // Gets the element in this module with the given target_name, or returns a
205	  // NotFoundError.
206	  template <typename T>
207	  absl::StatusOr<T*> GetMemberOrError(std::string_view target_name) const {
208	    std::optional<T*> result = GetMember<T>(target_name);
209	    if (!result.has_value()) {
210	      return absl::NotFoundError(
211	          absl::StrFormat("No %s in module `%s` with name `%s`",
212	                          T::GetDebugTypeName(), name_, target_name));
213	    }
214	    return *result;
215	  }
216	
217	  std::optional<Function*> GetFunction(std::string_view target_name) const {
218	    return GetMember<Function>(target_name);
219	  }
220	
221	  // Gets a test construct in this module with the given "target_name", or
222	  // returns a NotFoundError.
223	  absl::StatusOr<TestFunction*> GetTest(std::string_view target_name) const {
224	    return GetMemberOrError<TestFunction>(target_name);
225	  }
226	  absl::StatusOr<TestProc*> GetTestProc(std::string_view target_name) const {
227	    return GetMemberOrError<TestProc>(target_name);
228	  }
229	  absl::StatusOr<ProcDef*> GetTestProcDef(std::string_view target_name) const {
230	    XLS_ASSIGN_OR_RETURN(ProcDef * proc,
231	                         GetMemberOrError<ProcDef>(target_name));
232	    XLS_RET_CHECK(GetAttribute(proc, AttributeKind::kTest).has_value());
233	    return proc;
234	  }
235	
236	  absl::Span<ModuleMember const> top() const { return top_; }
237	  absl::Span<ModuleMember> top() { return absl::MakeSpan(top_); }
238	
239	  // Returns whether the given node is disconnected from the AST, indicating it
240	  // was likely fabricated by type inference. We don't want to surface such
241	  // internal nodes in some contexts, e.g. in language server adapter
242	  // functionality.
243	  bool IsSyntheticNode(const AstNode* node) const {
244	    // It's synthetic if it's a top-level node that is not in the top set (the
245	    // set is populated by the parser). Note that ColonRef is a special case
246	    // here, because when it's the definition in a `TypeRef`, the parser
247	    // actually creates it as a disconnected node.
248	    if (node->parent() == nullptr && node->kind() != AstNodeKind::kColonRef &&
249	        !top_set_.contains(node)) {
250	      return true;
251	    }
252	
253	    // It's synthetic if it's an internally-generated TVTA. Note that there are
254	    // user-written TVTAs, which are entities whose type is a `T: type` kind of
255	    // parametric, and these are not marked internal.
256	    return node->kind() == AstNodeKind::kTypeAnnotation &&
257	           absl::down_cast<const TypeAnnotation*>(node)->annotation_kind() ==
258	               TypeAnnotationKind::kTypeVariable &&
259	           absl::down_cast<const TypeVariableTypeAnnotation*>(node)->internal();
260	  }
261	
262	  // Finds the first top-level member in top() with the given "target" name as
263	  // an identifier.
264	  std::optional<ModuleMember*> FindMemberWithName(std::string_view target);
265	  std::optional<const ModuleMember*> FindMemberWithName(
266	      std::string_view target) const;
267	
268	  // Returns whether the given node is a public member of this module.
269	  bool IsPublicMember(const AstNode& node) const;
270	
271	  const StructDef* FindStructDef(const Span& span) const;
272	
273	  const ProcDef* FindProcDef(const Span& span) const;
274	
275	  const EnumDef* FindEnumDef(const Span& span) const;
276	
277	  // Obtains all the type definition nodes in the module; e.g. TypeAlias,
278	  // StructDef, EnumDef.
279	  absl::flat_hash_map<std::string, TypeDefinition> GetTypeDefinitionByName()
280	      const;
281	
282	  // Obtains all the type definition nodes in the module in module-member order.
283	  std::vector<TypeDefinition> GetTypeDefinitions() const;
284	
285	  absl::StatusOr<TypeDefinition> GetTypeDefinition(std::string_view name) const;
286	
287	  // Retrieves a constant node from this module with the target name as its
288	  // identifier, or a NotFound error if none can be found.
289	  absl::StatusOr<ConstantDef*> GetConstantDef(std::string_view target);
290	
291	  absl::flat_hash_map<std::string, Import*> GetImportByName() const {
292	    return GetTopWithTByName<Import>();
293	  }
294	  absl::flat_hash_map<std::string, Function*> GetFunctionByName() const {
295	    return GetTopWithTByName<Function>();
296	  }
297	  absl::flat_hash_map<std::string, QuickCheck*> GetQuickCheckByName() const {
298	    return GetTopWithTByName<QuickCheck>();
299	  }
300	
301	  std::vector<QuickCheck*> GetQuickChecks() const {
302	    return GetTopWithT<QuickCheck>();
303	  }
304	  std::vector<StructDef*> GetStructDefs() const {
305	    return GetTopWithT<StructDef>();
306	  }
307	  std::vector<ProcDef*> GetProcDefs() { return GetTopWithT<ProcDef>(); }
308	
309	  std::vector<Proc*> GetProcs() const { return GetTopWithT<Proc>(); }
310	  std::vector<TestProc*> GetTestProcs() const {
311	    return GetTopWithT<TestProc>();
312	  }
313	
314	  std::vector<Function*> GetFunctions() const {
315	    return GetTopWithT<Function>();
316	  }
317	
318	  std::vector<Impl*> GetImpls() const { return GetTopWithT<Impl>(); }
319	
320	  // Returns the identifiers for all functions within this module (in the order
321	  // in which they are defined).
322	  std::vector<std::string> GetFunctionNames() const;
323	
324	  // Returns the identifiers for all tests within this module (in the order in
325	  // which they are defined).
326	  std::vector<std::string> GetTestNames() const;
327	
328	  // Returns the identifiers for all QuickChecks within this module (in the
329	  // order in which they are defined).
330	  std::vector<std::string> GetQuickCheckNames() const;
331	
332	  const std::string& name() const { return name_; }
333	
334	  void SetName(std::string name) { name_ = std::move(name); }
335	
336	  const std::optional<std::filesystem::path>& fs_path() const {
337	    return fs_path_;
338	  }
339	
340	  // Finds a node with the given kind and /exactly/ the same span as "target".
341	  const AstNode* FindNode(AstNodeKind kind, const Span& target) const;
342	
343	  // Finds all the AST nodes in the module with spans that intercept the given
344	  // "target" position.
345	  std::vector<const AstNode*> FindIntercepting(const Pos& target) const;
346	
347	  // Finds all the AST nodes that fall within the given span.
348	  std::vector<const AstNode*> FindContained(const Span& target) const;
349	
350	  // Tags this module as having the given module-level attribute "attribute".
351	  void AddAttribute(ModuleAttribute attribute,
352	                    std::optional<Span> span = std::nullopt) {
353	    attributes_.insert(attribute);
354	    if (span.has_value()) {
355	      if (!attribute_start_.has_value() || span->start() < *attribute_start_) {
356	        attribute_start_ = span->start();
357	      }
358	      if (!attribute_limit_.has_value() || *attribute_limit_ < span->limit()) {
359	        attribute_limit_ = span->limit();
360	      }
361	    }
362	  }
363	
364	  // Returns all the module-level attribute tags.
365	  const absl::btree_set<ModuleAttribute>& attributes() const {
366	    return attributes_;
367	  }
368	
369	  // Returns the span of all the module-level attribute tags.
370	  std::optional<Span> GetAttributeSpan() const {
371	    if (!attribute_start_.has_value()) {
372	      return std::nullopt;
373	    }
374	    CHECK(attribute_limit_.has_value());
375	    return Span(*attribute_start_, *attribute_limit_);
376	  }
377	
378	  FileTable* file_table() const { return file_table_; }
379	
380	  absl::Status SetConfiguredValues(std::vector<std::string> configured_values) {
381	    absl::flat_hash_map<std::string, std::string> configured_values_map;
382	    for (const auto& item : configured_values) {
383	      std::vector<std::string> key_value =
384	          absl::StrSplit(item, absl::MaxSplits(':', 1));
385	      if (key_value.size() != 2) {
386	        return absl::InvalidArgumentError(absl::StrFormat(
387	            "Configured value '%s' is not in the form 'key:value'.", item));
388	      }
389	      configured_values_map.insert({key_value[0], key_value[1]});
390	    }
391	    configured_values_ = std::move(configured_values_map);
392	    return absl::OkStatus();
393	  }
394	
395	  const absl::flat_hash_map<std::string, std::string>& configured_values()
396	      const {
397	    return configured_values_;
398	  }
399	
400	 private:
401	  template <typename T, typename... Args>
402	  T* MakeInternal(Args&&... args) {
403	    std::unique_ptr<T> node =
404	        std::make_unique<T>(this, std::forward<Args>(args)...);
405	    T* ptr = node.get();
406	    ptr->SetParentage();
407	    nodes_.push_back(std::move(node));
408	    return ptr;
409	  }
410	
411	  // Returns all of the elements of top_ that have the given variant type T.
412	  template <typename T>
413	  std::vector<T*> GetTopWithT() const {
414	    std::vector<T*> result;
415	    for (auto& member : top_) {
416	      if (std::holds_alternative<T*>(member)) {
417	        result.push_back(std::get<T*>(member));
418	      }
419	    }
420	    return result;
421	  }
422	
423	  // Returns all the elements of top_ that have the given variant type T, using
424	  // T's identifier as a key. (T must have a string identifier.)
425	  template <typename T>
426	  absl::flat_hash_map<std::string, T*> GetTopWithTByName() const {
427	    absl::flat_hash_map<std::string, T*> result;
428	    for (auto& member : top_) {
429	      if (std::holds_alternative<T*>(member)) {
430	        auto* c = std::get<T*>(member);
431	        result.insert({c->identifier(), c});
432	      }
433	    }
434	    return result;
435	  }
436	
437	  std::vector<std::string> GetMemberNames(const ModuleMember& member) const;
438	
439	  absl::Status CheckForCollision(
440	      ModuleMember member, const MakeCollisionError& make_collision_error);
441	
442	  template <typename It>
443	  absl::Status InsertTopAt(ModuleMember member, It it);
444	
445	  std::string name_;  // Name of this module.
446	
447	  // Optional filesystem path (may not be present e.g. for DSLX files created in
448	  // memory).
449	  std::optional<std::filesystem::path> fs_path_;
450	
451	  FileTable* file_table_;
452	
453	  std::vector<ModuleMember> top_;  // Top-level members of this module.
454	  std::vector<std::unique_ptr<AstNode>> nodes_;  // Lifetime-owned AST nodes.
455	
456	  // Same as `top_` but as a set, for quick contains() checks.
457	  absl::flat_hash_set<const AstNode*> top_set_;
458	
459	  // Map of top-level module member name to the member itself.
460	  absl::flat_hash_map<std::string, ModuleMember> top_by_name_;
461	
462	  // Builtin name definitions, which we common out on a per-module basis. Not
463	  // for any particular purpose at this time aside from cleanliness of not
464	  // having many definition nodes of the same builtin thing floating around.
465	  absl::flat_hash_map<std::string, BuiltinNameDef*> builtin_name_defs_;
466	
467	  absl::btree_set<ModuleAttribute> attributes_;
468	  std::optional<Pos> attribute_start_;
469	  std::optional<Pos> attribute_limit_;
470	
471	  // Map of values that can be accessed via configured_value_or calls from
472	  // DSLX code within this module.
473	  absl::flat_hash_map<std::string, std::string> configured_values_;
474	
475	  // The span of the module is only known once parsing has completed.
476	  //
477	  // Implementation note: this could be avoided by using a module builder until
478	  // all values are completed/availble, but there is a lot of state to carry in
479	  // the builder and marginal benefit to the builder over the
480	  // partially-completed object.)
481	  std::optional<Span> span_;
482	};
483	
484	// Helper for making a ternary expression conditional. This avoids the user
485	// needing to hand-craft the block nodes and such.
486	Conditional* MakeTernary(Module* module, const Span& span, Expr* test,
487	                         Expr* consequent, Expr* alternate);
488	
489	// Returns whether the given module member is annotated as public.
490	bool IsPublic(const ModuleMember& member);
491	
492	}  // namespace xls::dslx
493	
494	#endif  // XLS_DSLX_FRONTEND_MODULE_H_
