40	// Bindings (name references in the environment that map back to definition
41	// points in the AST) resolve to this BoundNode variant, which are all kinds of
42	// definitions.
43	using BoundNode =
44	    std::variant<EnumDef*, TypeAlias*, ConstantDef*, NameDef*, BuiltinNameDef*,
45	                 StructDef*, ProcDef*, Import*, UseTreeEntry*>;
46	
47	// Returns a string, useful for reporting in error messages, for the type of the
