51	// Encodes ParseError data in a canonical way inside of an invalid argument
52	// error.
53	//
54	// When these propagate up to a Python boundary we throw them as exceptions
55	// using the data encoded in the absl::Status message. See ParseErrorGetData()
56	// for the utility used to extract the data from the error message text.
57	inline absl::Status ParseErrorStatus(const Span& span, std::string_view message,
