100	// Maps identifiers to the AST node that bound that identifier (also known as
101	// the lexical environment).
102	//
103	// The datatype is "stackable" so that we can easily take the bindings at a
104	// given point in the program (say in a function) and extend it with a new scope
105	// by stacking a fresh Bindings object on top (also sometimes referred to as a
106	// "scope chain"). For example:
107	//
108	//    Binding builtin_bindings;
109	//    builtin_bindings.Add("range", m.Make<BuiltinNameDef>("range"));
110	//
111	//    // Create a fresh scope, with no need to copy the builtin_bindings object.
112	//    Bindings function_bindings(&builtin_bindings);
113	//    XLS_ASSIGN_OR_RETURN(Function* f, ParseFunction(&function_bindings));
114	//
115	// We can do this because bindings are immutable and stack according to lexical
116	// scope; new bindings in the worst case only shadow previous bindings.
117	class Bindings {
118	 public:
119	  explicit Bindings(Bindings* parent = nullptr);
120	
121	  // Too easy to confuse chaining a bindings object with its parent vs copy
122	  // constructing so we rely on an explicit Clone() call instead.
123	  Bindings(const Bindings& other) = delete;
124	
125	  // Moving is ok though.
126	  Bindings(Bindings&& other) = default;
127	  Bindings& operator=(Bindings&& other) = default;
128	
129	  void ConsumeLocalBindingsFrom(const Bindings& other) {
130	    for (const auto& [k, v] : other.local_bindings_) {
131	      local_bindings_[k] = v;
132	    }
133	  }
134	
135	  // The "Cronus" method. This adds a child's bindings to this object, i.e., it
136	  // "commits" changes made in a child Bindings to this parent object.
137	  void ConsumeChild(const Bindings* child) {
138	    CHECK_EQ(child->parent_, this);
139	    ConsumeLocalBindingsFrom(*child);
140	  }
141	
142	  // Returns whether there are any local bindings (i.e. bindings that are not
143	  // set in parent/ancestors).
144	  bool HasLocalBindings() const { return !local_bindings_.empty(); }
145	
146	  // Adds a local binding.
147	  void Add(std::string name, BoundNode binding) {
148	    // When parsing the builtins module, the parser creates normal NameDefs
149	    // for what are really builtins. This is fine as long as we don't let these
150	    // NameDefs shadow the corresponding BuiltinNameDefs for the same entities.
151	    // Without this check, a builtin that uses another builtin in its signature
152	    // would cause problems in type concretization.
153	    if (IsBuiltinModule()) {
154	      std::optional<BoundNode> existing = ResolveNode(name);
155	      if (existing.has_value() &&
156	          std::holds_alternative<BuiltinNameDef*>(*existing)) {
157	        return;
158	      }
159	    }
160	    local_bindings_[std::move(name)] = binding;
161	  }
162	
163	  void SetBuiltinModule(bool value) { builtin_module_ = value; }
164	  bool IsBuiltinModule() {
165	    return builtin_module_ ||
166	           (parent_ != nullptr && parent_->IsBuiltinModule());
167	  }
168	
169	  // Returns whether the bindings are for a context that is inside a trait.
170	  bool IsInTrait() const {
171	    return in_trait_ || (parent_ != nullptr && parent_->IsInTrait());
172	  }
173	
174	  // Returns whether `self` has been set to anything on this object or one of
175	  // its parents.
176	  bool HasSelf() const {
177	    return self_.has_value() || (parent_ != nullptr && parent_->HasSelf());
178	  }
179	
180	  // Returns the `TypeAnnotation` for the struct that `self` indicates in the
181	  // current context. This only returns an annotation in an `impl`. In a trait
182	  // or other context, it returns `nullopt`.
183	  std::optional<TypeAnnotation*> GetImplSelf() const {
184	    if (!self_.has_value() && parent_ != nullptr) {
185	      return parent_->GetImplSelf();
186	    }
187	    if (self_.has_value() && std::holds_alternative<TypeAnnotation*>(*self_)) {
188	      return std::get<TypeAnnotation*>(*self_);
189	    }
190	    return std::nullopt;
191	  }
